<script lang="ts">
  import { onMount } from 'svelte';
  import ThemeToggle from './shared/ThemeToggle.svelte';
  import SupportAgents from './shared/SupportAgents.svelte';
  import type { SupportAgent } from './shared/supportAgents';
  interface AgentCard { id: string; name: string; description: string; stage: string; mark: string; capabilities: string[]; inputs: string; outputs: string; files: string[]; studio_url: string; version: string; run_count: number; active_count: number }
  let agents = $state<AgentCard[]>([]);
  let supportAgents = $state<SupportAgent[]>([]);
  let stages = $state<{ name: string; agent: string | null }[]>([]);
  let error = $state(''), loaded = $state(false);
  async function refresh() {
    try {
      const response = await fetch('/workspace/agents');
      if (!response.ok) throw new Error(response.status === 404 ? 'Restart just dev to load the agent catalog.' : 'Could not load the agent workspace. Check that just dev is running.');
      const data = await response.json(); agents = data.agents; supportAgents = data.support_agents || []; stages = data.stages; loaded = true; error = '';
    } catch (cause) { error = (cause as Error).message; }
  }
  onMount(() => { void refresh(); const poll = setInterval(() => void refresh(), 5000); return () => clearInterval(poll); });
</script>

<svelte:head><title>Code Studio · Agents</title></svelte:head>
<div class="agents-app">
  <header><a class="brand" href="/">⌘ <strong>Code Studio</strong></a><div class="header-actions"><ThemeToggle /><div><span class="local-dot"></span>Local workspace</div></div></header>
  <div class="layout">
    <aside><div class="workspace"><span class="workspace-icon">CS</span><div>Team workspace<small>LOCAL DEVELOPMENT</small></div></div><span class="nav-label">WORKSPACE</span><a class="nav-link active" href="/" aria-current="page"><span>◈</span>Agents<small>{agents.length + supportAgents.length || ''}</small></a><a class="nav-link" href="?view=work"><span aria-hidden="true">✦</span>Features</a><div class="sidebar-note"><span>BUILT TOGETHER</span><p>Your team shapes how each agent thinks, works, and collaborates.</p></div></aside>
    <main>
      <div class="page-heading"><div class="eyebrow">YOUR SDLC WORKSPACE</div><h1>Agents</h1><p>A team of agents, built by your team.<br>Customize their behavior together, then put them to work on a codebase.</p><a class="start-feature io-button io-button--primary" href="?view=work&new=1">＋ Start a feature</a></div>
      {#if error}<div class="error" role="alert">{error}<button class="io-button io-button--secondary" onclick={() => void refresh()}>Retry</button></div>{/if}
      <div class="section-heading"><h2>Workflow agents <span>{agents.length}</span></h2><span>Shared definitions · Versioned runs</span></div>
      <div class="agent-grid">
        {#each agents as agent}
          <article class:review={agent.id === 'review'}>
            <div class="card-top"><span class="agent-icon">{['✧', '⌘', '◇', '⌥', '✓', '↗'][agents.indexOf(agent)]}</span><span class="stage">{agent.stage}</span><span class="number">{agent.mark}</span></div>
            <h2>{agent.name}{' '}<span>agent</span></h2><p class="description">{agent.description}</p>
            <div class="capabilities">{#each agent.capabilities as capability}<span>{{stage_list_files: 'Browse code', stage_read_file: 'Read files', stage_write_file: 'Edit files', stage_run_check: 'Run checks', create_release_preview: 'Package preview'}[capability] || capability}</span>{/each}</div>
            <div class="contract"><div><span>TAKES IN</span><p>{agent.inputs}</p></div><div><span>PRODUCES</span><p>{agent.outputs}</p></div></div>
            <div class="card-meta"><span>{agent.files.length} shared files</span><span>{agent.active_count ? agent.active_count + ' running · ' : ''}{agent.run_count} {agent.run_count === 1 ? 'task' : 'tasks'} run</span><code>v {agent.version.slice(0, 8)}</code></div>
            <a class="open" href={agent.studio_url}>Open in Agent Studio <span>↗</span></a>
          </article>
        {/each}
      </div>
      {#if !loaded && !error}<p class="loading">Loading your agents…</p>{/if}
      {#if supportAgents.length}<SupportAgents agents={supportAgents} />{/if}
      <section class="ecosystem"><div class="ecosystem-heading"><div><span class="eyebrow">AN EVOLVING AGENT TEAM</span><h2>From idea to deployment</h2></div><span class="roadmap">CONNECTED WORKFLOW</span></div><p>Six focused agents carry a feature from a shared idea to a local release preview. Jump into any feature to see its progress, discuss the work, and customize the agents behind it.</p><div class="stages">{#each stages as stage}<div class:available={!!stage.agent}><span class="stage-dot"></span><strong>{stage.name}</strong><small>{stage.agent === 'planner' || stage.agent === 'review' ? 'Team approval' : 'Automatic handoff'}</small></div>{/each}</div><p class="handoff-note">Your team approves the plan before implementation and the review before release preparation. The Deployment agent produces a local preview and deployment plan.</p></section>
      <section class="how"><div><span>01</span><h3>Customize together</h3><p>Edit Python flows, prompts, and settings in a shared Studio.</p></div><div><span>02</span><h3>Run a saved version</h3><p>Start with Code Studio’s current files or a Git branch. Each stage records exactly which agent definition ran.</p></div><div><span>03</span><h3>Review and improve</h3><p>Discuss the output, refine the agent, and run it again.</p></div></section>
    </main>
  </div>
</div>

